import{c as a,Q as e,j as l,m as r}from"./chunks/framework.DOi4mjdC.js";const C=JSON.parse('{"title":"CrossCoreWaitFlag(ISASI)","description":"","frontmatter":{},"headers":[{"level":1,"title":"CrossCoreWaitFlag\\\\(ISASI\\\\)","slug":"crosscorewaitflagisasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/同步控制/核间同步/CrossCoreWaitFlag(ISASI).md","filePath":"api/SIMD-API/基础API/同步控制/核间同步/CrossCoreWaitFlag(ISASI).md"}'),s={name:"api/SIMD-API/基础API/同步控制/核间同步/CrossCoreWaitFlag(ISASI).md"};function o(d,t,i,n,h,I){return e(),l("div",null,[...t[0]||(t[0]=[r(`<h1 id="crosscorewaitflag-isasi" tabindex="-1">CrossCoreWaitFlag(ISASI) <a class="header-anchor" href="#crosscorewaitflag-isasi" aria-label="Permalink to &quot;CrossCoreWaitFlag\\(ISASI\\)&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>面向分离模式的核间同步控制接口。该接口和<a href="./CrossCoreSetFlag(ISASI).html">CrossCoreSetFlag</a>接口配合使用。具体使用方法请参考<a href="./CrossCoreSetFlag(ISASI).html">CrossCoreSetFlag</a>。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;uint8_t modeId = 0, pipe_t pipe = PIPE_S&gt;</span></span>
<span class="line"><span>__aicore__ inline void CrossCoreWaitFlag(uint16_t flagId)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>modeId</td><td>核间同步的模式，取值如下： 模式0：AI Core核间的同步控制。模式1：AI Core内部，Vector核（AIV）之间的同步控制。模式2：AI Core内部，Cube核（AIC）与Vector核（AIV）之间的同步控制。模式4：AI Core内部，AIC与AIV之间的同步控制。AIV0与AIV1可单独触发AIC等待。</td></tr><tr><td>pipe</td><td>设置这条指令所在的流水类型，流水类型可参考硬件流水类型。 特别地，PIPE_S流水类型仅Ascend 950PR/Ascend 950DT支持。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>flagId</td><td>输入</td><td>核间同步的标记。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，取值范围是0-10。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，取值范围是0-10。 Ascend 950PR/Ascend 950DT，取值范围如下： AIV0发起的flagId 0-10的CrossCoreSetFlag操作对应AIC CrossCoreWaitFlag中flagId 0-10的操作。 AIV1发起的flagId 0-10的CrossCoreSetFlag操作对应AIC CrossCoreWaitFlag中flagId 16-26的操作。 AIC发起的flagId 0-10的CrossCoreSetFlag操作对应AIV0 CrossCoreWaitFlag中flagId 0-10的操作。 AIC发起的flagId 16-26的CrossCoreSetFlag操作对应AIV1 CrossCoreWaitFlag中flagId 0-10的操作。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>使用该同步接口时，需要按照如下规则<a href="./../../Kernel-Tiling/设置Kernel类型.html">设置Kernel类型</a>：</p><ul><li>在纯Vector/Cube场景下，需设置Kernel类型为KERNEL_TYPE_MIX_AIV_1_0或KERNEL_TYPE_MIX_AIC_1_0。</li><li>对于Vector和Cube混合场景，需根据实际情况灵活配置Kernel类型。</li></ul></li><li><p>CrossCoreWaitFlag必须与<a href="./CrossCoreSetFlag(ISASI).html">CrossCoreSetFlag</a>接口配合使用，避免计算核一直处于阻塞阶段。</p></li><li><p>如果执行CrossCoreWaitFlag时该flagId的计数器的值为0，则CrossCoreWaitFlag之后的所有指令都将被阻塞，直到该flagId的计数器的值不为0。同一个flagId的计数器最多设置15次。</p></li><li><p>使用该接口模式0时，建议开启batchmode模式，使算子独占全部所需核资源，否则可能因满足以下条件导致死锁：</p><ul><li>多流并发场景（≥2条执行流）。</li><li>≥2个算子并发执行。</li><li>所有并发算子的核数总和超过物理核数。</li><li>≥2个并发算子使用了核间同步功能。</li></ul><p>具体而言，在多流场景下，某条流的核间同步算子虽分配到n个物理核，但可能仅有n-m个核先被调度执行，而其余m个核因被其他流的核间同步算子抢占而尚未启动。先启动的n-m个核执行到核间同步时等待剩余m核完成，而剩余m核因被其他流的核间同步算子占用而无法释放，形成死锁。</p><p>Kernel直调场景下通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/guide/%E7%BC%96%E7%A8%8B%E6%8C%87%E5%8D%97/%E8%AF%AD%E8%A8%80%E6%89%A9%E5%B1%95%E5%B1%82/SIMD-BuiltIn%E5%85%B3%E9%94%AE%E5%AD%97.md" target="_blank" rel="noreferrer">__schedmode__(mode)</a>限定符来设置batchmode模式；工程化算子开发场景下，通过TilingContext的SetScheduleMode接口来设置batchmode模式，具体请参考《基础数据结构和接口》。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>请参考<a href="./CrossCoreSetFlag(ISASI).html#section837496171220">调用示例</a>。</p>`,18)])])}const c=a(s,[["render",o]]);export{C as __pageData,c as default};
